/**
 * Stackra file contract:
 * Purpose: unit tests of `provenanceComment`: names the generator and the subject, never a path.
 * Boundary: test only.
 * Runtime: node (vitest)
 * Governing contract: ADR 0022 (test placement); ADR 0282 (decision 2).
 */
import { describe, expect, it } from "@stackra/testing";

import { provenanceComment } from "#core/functions/provenance-comment.function";

describe("provenanceComment", () => {
  it("is one HTML comment naming the generator and the subject", () => {
    expect(provenanceComment("vellum", 'skill "naming"')).toBe(
      '<!-- generated by vellum from skill "naming"; edit the source, not this file -->',
    );
  });
});
